00034     private function ensureMkcertExeExists()
00035     {
00036         $mkcertExe = Path::getMkcertExe();
00037         if (file_exists($mkcertExe)) {
00038             return true;
00039         }
00040 
00041         Log::error('mkcert.exe missing at: ' . $mkcertExe . '. It must be fetched during build time (prepareBase/buildFull/buildLite).');
00042         return false;
00043     }
