00050     private function ensureSslDirExists()
00051     {
00052         $sslPath = Path::getSslPath();
00053         if (!is_dir($sslPath)) {
00054             Log::info('SSL directory missing, creating: ' . $sslPath);
00055             if (mkdir($sslPath, 0700, true)) {
00056                 @chmod($sslPath, 0700);
00057                 // Create .gitignore if the directory was just created
00058                 $gitignorePath = $sslPath . '/.gitignore';
00059                 if (!file_exists($gitignorePath)) {
00060                     file_put_contents($gitignorePath, '# git holder' . PHP_EOL);
00061                 }
00062             } else {
00063                 Log::error('Failed to create SSL directory: ' . $sslPath);
00064             }
00065         } else {
00066             // Even if directory exists, ensure .gitignore is present
00067             $gitignorePath = $sslPath . '/.gitignore';
00068             if (!file_exists($gitignorePath)) {
00069                 file_put_contents($gitignorePath, '# git holder' . PHP_EOL);
00070             }
00071         }
00072 
00073         if (!is_readable($sslPath) || !is_writable($sslPath)) {
00074             Log::warning('SSL directory is not fully accessible. Attempting to relax permissions: ' . $sslPath);
00075 
00076             // Set permissive permissions for local dev environment (0755 allows owner RWX, group/others RX)
00077             @chmod($sslPath, 0755);
00078             clearstatcache(true, $sslPath);
00079 
00080             if (!is_readable($sslPath) || !is_writable($sslPath)) {
00081                 Log::error('SSL directory is still not readable/writable after permission adjustment: ' . $sslPath);
00082             }
00083         }
00084 
00085         return $sslPath;
00086     }
