00093     public function makeRootCa()
00094     {
00095         if (!$this->ensureMkcertExeExists()) {
00096             return false;
00097         }
00098         $destPath = Path::getSslPath();
00099         $mkcertExe = Path::getMkcertExe();
00100 
00101         Log::info('Creating new Root CA and installing it...');
00102         
00103         $rootCaPath = Path::getSslPath() . '/' . Path::getMkcertRootCaName();
00104         $batch = 'SET "CAROOT=' . Path::formatWindowsPath(Path::getSslPath()) . '"' . PHP_EOL;
00105         $batch .= '"' . $mkcertExe . '" -uninstall' . PHP_EOL;
00106         $batch .= '"' . $mkcertExe . '" -install' . PHP_EOL;
00107         $batch .= 'IF EXIST "' . Path::formatWindowsPath($rootCaPath) . '" (ECHO OK)' . PHP_EOL;
00108         
00109         // Wait for the Root CA file to appear or timeout
00110         $result = Batch::exec('mkcertMakeRootCa', $batch);
00111         
00112         if (!file_exists($rootCaPath)) {
00113             Log::error('Failed to create Root CA file at: ' . $rootCaPath);
00114             return false;
00115         }
00116 
00117         // Display info about the new Root CA
00118         $batch = 'SET "CAROOT=' . Path::formatWindowsPath(Path::getSslPath()) . '"' . PHP_EOL;
00119         $batch .= '"' . $mkcertExe . '" -CAROOT' . PHP_EOL;
00120         $caRootInfo = Batch::exec('mkcertCaRootInfo', $batch);
00121         if ($caRootInfo && isset($caRootInfo[0])) {
00122             Log::info('mkcert CAROOT is set to: ' . $caRootInfo[0]);
00123         }
00124 
00125         Log::info('Root CA created. Rebuilding all existing certificates and ensuring localhost exists...');
00126         
00127         // Ensure localhost is created/rebuilt
00128         $this->createCrt('localhost');
00129         
00130         return $this->rebuildAllCerts();
00131     }
