00138     public function rebuildAllCerts()
00139     {
00140         $certs = $this->getCrts();
00141         $success = true;
00142 
00143         foreach ($certs as $cert) {
00144             Log::info('Rebuilding certificate: ' . $cert);
00145             if (!$this->createCrt($cert)) {
00146                 Log::error('Failed to rebuild certificate: ' . $cert);
00147                 $success = false;
00148             }
00149         }
00150 
00151         return $success;
00152     }
