00163     private function validateCertificateName($name)
00164     {
00165         if (empty($name)) {
00166             return false;
00167         }
00168 
00169         // Filesystem-safe whitelist with mandatory alphanumeric first character:
00170         // - Prevents CLI flag injection (leading `-`)
00171         // - Prevents relative path traversal (leading `.`)
00172         // - Allows remaining chars to be alphanumeric, dots, dashes, underscores
00173         if (!preg_match('/^[a-zA-Z0-9][a-zA-Z0-9._-]*$/', $name)) {
00174             return false;
00175         }
00176 
00177         return true;
00178     }
00179 
00187     public function createCrt($name, $destPath = null)
00188     {
00189         Log::trace('createCrt called for: ' . $name . ($destPath ? ' (dest: ' . $destPath . ')' : ''));
00190 
00191         if (!$this->validateCertificateName($name)) {
00192             Log::error('Invalid certificate name: ' . $name);
00193             return false;
00194         }
00195 
00196         if (!$this->ensureMkcertExeExists()) {
00197             return false;
00198         }
00199         if (empty($destPath)) {
00200             $destPath = $this->ensureSslDirExists();
00201         }
00202         $mkcertExe = Path::getMkcertExe();
00203 
00204         if (!$this->ensureRootCaExists($destPath)) {
00205             Log::error('Failed to ensure Root CA exists for: ' . $name);
00206             return false;
00207         }
00208 
00209         $crtPath = '"' . Path::formatWindowsPath($destPath . '/' . $name . '.crt') . '"';
00210         $pubPath = '"' . Path::formatWindowsPath($destPath . '/' . $name . '.pub') . '"';
00211         $keyPath = '"' . Path::formatWindowsPath($destPath . '/' . $name . '.ppk') . '"'; // Using .ppk as requested in previous tasks
00212         $opensslExe = '"' . Path::formatWindowsPath(Path::getOpenSslExe()) . '"';
00213 
00214         $batch = 'SET "CAROOT=' . Path::formatWindowsPath($destPath) . '"' . PHP_EOL;
00215 
00216         $mkcertNames = '"' . $name . '"';
00217         if ($name === 'localhost') {
00218             $mkcertNames .= ' 127.0.0.1 ::1';
00219         } else {
00220             $mkcertNames .= ' "*.' . $name . '" localhost 127.0.0.1 ::1';
00221         }
00222 
00223         Log::trace('Executing mkcert for "' . $name . '"');
00224         // Use -- to terminate flag parsing before hostname arguments as defense-in-depth
00225         $batch .= '"' . $mkcertExe . '" -cert-file ' . $crtPath . ' -key-file ' . $keyPath . ' -- ' . $mkcertNames . PHP_EOL;
00226         $batch .= $opensslExe . " rsa -in " . $keyPath . " -out " . $keyPath . " -passin pass:" . PHP_EOL;
00227         $batch .= "COPY /Y " . $keyPath . " " . $pubPath . PHP_EOL;
00228         $batch .= 'IF EXIST ' . $crtPath . ' IF EXIST ' . $keyPath . ' ECHO OK' . PHP_EOL;
00229 
00230         Log::trace('Creating SSL Certificate for "' . $name . '" using mkcert. Batch content: ' . $batch);
00231         $result = Batch::exec('createCertificateMkcert', $batch);
00232 
00233         if ($result === false || !is_array($result)) {
00234             Log::error('Batch execution failed for mkcert generation of "' . $name . '". Check logs for createCertificateMkcert.');
00235             return false;
00236         }
00237 
00238         $success = false;
00239         foreach ($result as $line) {
00240             if (trim($line) === 'OK') {
00241                 $success = true;
00242                 break;
00243             }
00244         }
00245         
00246         if (!$success) {
00247             Log::error('mkcert generation for "' . $name . '" did not return OK. Output: ' . implode(' | ', $result));
00248         }
00249         Log::trace('mkcert generation for "' . $name . '": ' . ($success ? 'SUCCESS' : 'FAILURE'));
00250 
00251         return $success;
00252     }
00253 
00260     private function ensureRootCaExists($destPath)
00261     {
00262         if (!$this->ensureMkcertExeExists()) {
00263             return false;
00264         }
00265         $mkcertExe = Path::getMkcertExe();
00266 
00267         $rootCaPath = $destPath . '/' . Path::getMkcertRootCaName(); // mkcert default root CA name
00268         if (!file_exists($rootCaPath)) {
00269             Log::info('Root CA missing at ' . $rootCaPath . '. Running mkcert -install');
00270             $batch = 'SET "CAROOT=' . Path::formatWindowsPath($destPath) . '"' . PHP_EOL;
00271             $batch .= '"' . $mkcertExe . '" -install' . PHP_EOL;
00272             $batch .= 'IF EXIST "' . Path::formatWindowsPath($rootCaPath) . '" (ECHO OK)' . PHP_EOL;
00273             $result = Batch::exec('mkcertInstall', $batch);
00274             
00275             if ($result === false) {
00276                 Log::error('Batch execution failed for mkcert -install');
00277                 return false;
00278             }
00279 
00280             // Re-check after installation
00281             if (!file_exists($rootCaPath)) {
00282                 Log::error('Root CA still missing after mkcert -install at: ' . $rootCaPath);
00283                 return false;
00284             }
00285             Log::info('Root CA successfully created and verified.');
00286         }
00287         return true;
00288     }
