00460     public function getCrts()
00461     {
00462         $sslPath = $this->ensureSslDirExists();
00463         $certs = [];
00464         if (is_dir($sslPath)) {
00465             $files = glob($sslPath . '/*.crt');
00466             if ($files !== false) {
00467                 foreach ($files as $file) {
00468                     $certs[] = basename($file, '.crt');
00469                 }
00470             }
00471         }
00472         sort($certs);
00473         return $certs;
00474     }
