00482     public function isExpired($name)
00483     {
00484         $crtPath = Path::getSslPath() . '/' . $name . '.crt';
00485         $pubPath = Path::getSslPath() . '/' . $name . '.pub';
00486 
00487         if (!is_file($crtPath)) {
00488             Log::trace('SSL certificate file missing: ' . $crtPath);
00489             return true;
00490         }
00491 
00492         if (!is_file($pubPath)) {
00493             Log::trace('SSL public certificate file missing: ' . $pubPath);
00494             return true;
00495         }
00496 
00497         if (!extension_loaded('openssl')) {
00498             Log::warning('OpenSSL extension not loaded. Cannot parse certificate for expiry check. Assuming NOT expired if file exists.');
00499             return false;
00500         }
00501 
00502         $crtContent = file_get_contents($crtPath);
00503         if ($crtContent === false) {
00504             Log::error('Could not read certificate file: ' . $crtPath);
00505             return true;
00506         }
00507 
00508         $certInfo = openssl_x509_parse($crtContent);
00509         if ($certInfo === false) {
00510             Log::error('Could not parse certificate: ' . $crtPath . '. OpenSSL error: ' . openssl_error_string());
00511             return true;
00512         }
00513 
00514         if (isset($certInfo['validTo_time_t'])) {
00515             $isExpired = $certInfo['validTo_time_t'] < time();
00516             if ($isExpired) {
00517                 Log::trace('SSL certificate expired: ' . $name . ' (Expired on ' . date('Y-m-d H:i:s', $certInfo['validTo_time_t']) . ')');
00518             }
00519             return $isExpired;
00520         }
00521 
00522         Log::error('Could not find expiry date in certificate: ' . $crtPath);
00523         return true;
00524     }
