00533     public function removeCrt($name, $destPath = null)
00534     {
00535         if ($name === 'localhost') {
00536             Log::warning('Attempted to remove protected "localhost" certificate. Operation cancelled.');
00537             return false;
00538         }
00539         $destPath = empty($destPath) ? $this->ensureSslDirExists() : $destPath;
00540 
00541         // Basic validation for name to prevent arbitrary file deletion
00542         if (!preg_match('/^[a-zA-Z0-9._-]+$/', $name)) {
00543             Log::error('Invalid certificate name for removal: ' . $name);
00544             return false;
00545         }
00546 
00547         $ppkPath = $destPath . '/' . $name . '.ppk';
00548         $crtPath = $destPath . '/' . $name . '.crt';
00549         $pubPath = $destPath . '/' . $name . '.pub';
00550 
00551         Log::info('Removing SSL certificate: ' . $name . ' from ' . $destPath);
00552         return @unlink($ppkPath) && @unlink($crtPath) && @unlink($pubPath);
00553     }
